+/// Parses and canonicalizes a credential-free HTTP(S) registry endpoint.
+///
+/// One resolver owns this normalization so observation and dispatch never
+/// disagree about a destination because of host casing, a default port, or a
+/// trailing slash. Credentials, query parameters, and fragments are rejected
+/// rather than normalized away because they must never become durable config.
+fn normalize_registry_url(registry: &str, field: &'static str, raw: &str) -> Result<String, ConfigError> {
+    let mut url = Url::parse(raw).map_err(|error| ConfigError::InvalidRegistryEndpoint {
+        registry: registry.to_string(),
+        field,
+        value: raw.to_string(),
+        reason: error.to_string(),
+    })?;
+    if !matches!(url.scheme(), "http" | "https") {
+        return Err(ConfigError::InvalidRegistryEndpoint {
+            registry: registry.to_string(),
+            field,
+            value: raw.to_string(),
+            reason: "scheme must be http or https".to_string(),
+        });
+    }
+    if url.host_str().is_none() || url.cannot_be_a_base() {
+        return Err(ConfigError::InvalidRegistryEndpoint {
+            registry: registry.to_string(),
+            field,
+            value: raw.to_string(),
+            reason: "URL must have an authority and hierarchical path".to_string(),
+        });
+    }
+    if !url.username().is_empty() || url.password().is_some() {
+        return Err(ConfigError::InvalidRegistryEndpoint {
+            registry: registry.to_string(),
+            field,
+            value: raw.to_string(),
+            reason: "userinfo is forbidden".to_string(),
+        });
+    }
+    if url.query().is_some() || url.fragment().is_some() {
+        return Err(ConfigError::InvalidRegistryEndpoint {
+            registry: registry.to_string(),
+            field,
+            value: raw.to_string(),
+            reason: "query parameters and fragments are forbidden".to_string(),
+        });
+    }
+
+    if matches!((url.scheme(), url.port()), ("http", Some(80)) | ("https", Some(443))) {
+        url.set_port(None).map_err(|()| ConfigError::InvalidRegistryEndpoint {
+            registry: registry.to_string(),
+            field,
+            value: raw.to_string(),
+            reason: "default port could not be normalized".to_string(),
+        })?;
+    }
+    let normalized_path = if url.path() == "/" {
+        "/".to_string()
+    } else {
+        url.path().trim_end_matches('/').to_string()
+    };
+    url.set_path(&normalized_path);
+    Ok(url.to_string())
+}
