+        raw.registry_url.is_some(),
+        raw.upload_url.is_some(),
+        raw.metadata_url.is_some(),
+        raw.simple_url.is_some(),
+    ];
+    if !present.into_iter().any(|value| value) {
+        return Ok(None);
+    }
+
+    let invalid_shape = || ConfigError::InvalidRegistryEndpointShape {
+        registry: registry.to_string(),
+        ecosystem: kind,
+    };
+    match kind {
+        Ecosystem::Cargo
+            if raw.index_url.is_some()
+                && raw.api_url.is_some()
+                && raw.registry_url.is_none()
+                && raw.upload_url.is_none()
+                && raw.metadata_url.is_none()
+                && raw.simple_url.is_none() =>
+        {
+            Ok(Some(RegistryEndpoints::Cargo {
+                index: normalize_registry_url(registry, "index-url", raw.index_url.as_deref().expect("checked"))?,
+                api: normalize_registry_url(registry, "api-url", raw.api_url.as_deref().expect("checked"))?,
