+            found: registry.kind,
+        });
+    }
+    let endpoints = registry
+        .endpoints
+        .as_ref()
+        .ok_or_else(|| ConfigError::IncompleteReleaseRegistry {
+            profile: profile.to_string(),
+            registry: key.to_string(),
+        })?;
+    Ok((registry_key, endpoints))
+}
