+fn resolve_release_config(
+    raw: crate::config::raw::RawReleaseConfig,
+    registries: &BTreeMap<RegistryKey, RegistryConfig>,
+) -> Result<ReleaseConfig, ConfigError> {
+    if !is_canonical_release_name(&raw.product.name) {
+        return Err(ConfigError::InvalidReleaseProductName { name: raw.product.name });
+    }
+    let provenance_repository = GitHubRepository::parse(&raw.product.provenance_repository).map_err(|error| {
