+        }
+    })?;
+    if !is_safe_build_workflow(&raw.product.build_workflow) {
+        return Err(ConfigError::InvalidReleaseWorkflow {
+            workflow: raw.product.build_workflow,
+        });
+    }
+    let product = ReleaseProductConfig {
+        name: raw.product.name,
+        provenance_repository,
+        build_workflow: raw.product.build_workflow,
+    };
+
+    let mut profiles = BTreeMap::new();
+    let mut production_profile = None;
+    for (name, raw_profile) in raw.profiles {
+        if !is_canonical_release_name(&name) {
+            return Err(ConfigError::InvalidReleaseProfileName { name });
+        }
+        let kind = match raw_profile.kind.as_str() {
+            "production" => ReleaseProfileKind::Production,
+            "rehearsal" => ReleaseProfileKind::Rehearsal,
+            _ => {
+                return Err(ConfigError::InvalidReleaseProfileKind {
+                    profile: name,
+                    kind: raw_profile.kind,
+                })
+            }
+        };
+        let forge_repository = GitHubRepository::parse(&raw_profile.forge_repository).map_err(|error| {
+            ConfigError::InvalidReleaseRepository {
+                field: "release.profiles.*.forge-repository",
+                value: raw_profile.forge_repository.clone(),
+                reason: error.to_string(),
+            }
+        })?;
+        let (cargo_registry, _) = registry_binding(
+            registries,
+            &name,
+            &raw_profile.cargo_registry,
+            Ecosystem::Cargo,
+        )?;
+        let (npm_registry, _) =
+            registry_binding(registries, &name, &raw_profile.npm_registry, Ecosystem::Npm)?;
+        let (pypi_registry, _) =
+            registry_binding(registries, &name, &raw_profile.pypi_registry, Ecosystem::Pypi)?;
+
+        if kind == ReleaseProfileKind::Production {
+            if production_profile.replace(name.clone()).is_some() {
+                return Err(ConfigError::InvalidProductionProfileCount { found: 2 });
+            }
+        }
+        profiles.insert(
+            name,
+            ReleaseProfileConfig {
+                kind,
+                forge_repository,
+                cargo_registry,
+                npm_registry,
+                pypi_registry,
+            },
+        );
+    }
+
+    let production_profile = production_profile.ok_or(ConfigError::InvalidProductionProfileCount { found: 0 })?;
+    let production = profiles
+        .get(&production_profile)
+        .expect("production profile name came from this map");
+    for (name, rehearsal) in profiles
+        .iter()
+        .filter(|(_, profile)| profile.kind == ReleaseProfileKind::Rehearsal)
+    {
+        if rehearsal.forge_repository == production.forge_repository {
+            return Err(ConfigError::RehearsalDestinationNotIsolated {
+                profile: name.clone(),
+                destination: "forge repository",
+            });
+        }
+        for (ecosystem, rehearsal_key, production_key) in [
+            (Ecosystem::Cargo, &rehearsal.cargo_registry, &production.cargo_registry),
+            (Ecosystem::Npm, &rehearsal.npm_registry, &production.npm_registry),
+            (Ecosystem::Pypi, &rehearsal.pypi_registry, &production.pypi_registry),
+        ] {
+            let rehearsal_endpoints = registries
+                .get(rehearsal_key)
+                .and_then(|registry| registry.endpoints.as_ref())
+                .expect("profile registry was validated above");
+            let production_endpoints = registries
+                .get(production_key)
+                .and_then(|registry| registry.endpoints.as_ref())
+                .expect("profile registry was validated above");
+            if rehearsal_endpoints
+                .urls()
+                .iter()
+                .any(|candidate| production_endpoints.urls().contains(candidate))
+            {
+                return Err(ConfigError::RehearsalDestinationNotIsolated {
+                    profile: name.clone(),
+                    destination: match ecosystem {
+                        Ecosystem::Cargo => "Cargo endpoint set",
+                        Ecosystem::Npm => "npm endpoint set",
+                        Ecosystem::Pypi => "PyPI endpoint set",
+                        _ => unreachable!("only releasable registry ecosystems are compared"),
+                    },
+                });
+            }
+        }
+    }
+
+    Ok(ReleaseConfig {
+        product,
+        profiles,
+        production_profile,
+    })
+}
*** End Patch";
