+        Ok(None) => return OperationObservation::Absent,
+        Err(failure) => return OperationObservation::Unverifiable(failure),
+    };
+    let expected_slots = validated
+        .intent()
+        .slots()
+        .iter()
+        .filter(|slot| slot.release() == Some(release))
+        .cloned()
+        .collect::<Vec<_>>();
+    let expected_names = expected_slots
+        .iter()
+        .map(|slot| slot.file_name().to_string())
+        .collect::<BTreeSet<_>>();
+    if let Some(file_name) = observed.assets.keys().find(|name| !expected_names.contains(*name)) {
+        return OperationObservation::Conflict(ExternalConflict::UnexpectedForgeAsset {
+            file_name: file_name.clone(),
+        });
+    }
+    let mut exact = Vec::new();
+    let mut missing = BTreeSet::new();
+    for slot in expected_slots {
+        let Some(asset) = observed.assets.get(slot.file_name()) else {
+            missing.insert(MissingWork::ForgeAsset(slot));
+            continue;
+        };
+        match compare_forge_asset(artifacts, release, &slot, asset) {
+            OperationObservation::Exact(evidence) => exact.push(evidence),
+            other => return other,
+        }
+    }
+    if observed.draft {
+        missing.insert(MissingWork::PublishForgeRelease(release.clone()));
+        return OperationObservation::Incomplete(VerifiedPartialEvidence::new(exact, missing));
+    }
+    if !missing.is_empty() {
+        return OperationObservation::Conflict(ExternalConflict::PublishedReleaseIncomplete {
+            release: release.clone(),
+        });
+    }
+    OperationObservation::Exact(ReleaseObservationEvidence::forge_publish(
+        release.clone(),
+        artifacts.expectations().asset_roster_digest().clone(),
+    ))
+}
+
+fn compare_forge_asset(
+    artifacts: &ValidatedArtifactManifest<'_, '_>,
+    release: &ProductReleaseId,
+    slot: &ReleaseArtifactSlot,
+    observed: &GitHubAsset,
+) -> OperationObservation {
+    let expectations = artifacts.expectations();
+    let Some((expected_digest, expected_length)) = expectations.artifact(slot) else {
+        return OperationObservation::Unverifiable(ObservationFailure::Capability {
+            provider: ObservationProvider::ArtifactCapability,
+        });
+    };
+    if observed.byte_length != expected_length {
+        return OperationObservation::Conflict(ExternalConflict::ForgeAssetLength {
+            slot: slot.clone(),
+            observed: observed.byte_length,
+        });
+    }
+    let Some(observed_digest) = &observed.digest else {
+        return OperationObservation::Unverifiable(ObservationFailure::MissingDigest {
+            provider: ObservationProvider::GitHub,
+            file_name: slot.file_name().to_string(),
+        });
+    };
+    if observed_digest != expected_digest {
+        return OperationObservation::Conflict(ExternalConflict::ForgeAssetDigest {
+            slot: slot.clone(),
+            observed: observed_digest.clone(),
+        });
+    }
+    OperationObservation::Exact(ReleaseObservationEvidence::forge_asset(
+        release.clone(),
+        slot.clone(),
+        expected_digest.clone(),
+        expected_length,
+    ))
+}
