+fn require_exact_remote_tag(
+    artifacts: &ValidatedArtifactManifest<'_, '_>,
+    validated: &ValidatedReleaseIntent<'_>,
+) -> Option<OperationObservation> {
+    let operation = validated
+        .intent()
+        .operations()
+        .iter()
+        .find(|operation| matches!(operation.id(), ReleaseOperationId::ProductTag { .. }))?;
+    match validated.prepared_operation(operation.id()) {
+        Some(PreparedOperationView::ProductTag {
+            name,
+            target,
+            annotation,
+            remote_name,
+            ..
+        }) => match operation.id() {
+            ReleaseOperationId::ProductTag { release, .. } => {
+                match observe_tag(artifacts, validated, release, name, target, annotation, remote_name) {
+                    OperationObservation::Exact(_) => None,
+                    OperationObservation::Absent => {
+                        Some(OperationObservation::Conflict(ExternalConflict::RemoteTagMissingForForge))
+                    }
+                    other => Some(other),
+                }
+            }
+            _ => unreachable!("product-tag predicate returned another operation"),
+        },
+        _ => Some(OperationObservation::Unverifiable(ObservationFailure::Capability {
+            provider: ObservationProvider::PreparedCapability,
+        })),
+    }
+}
+
+fn github_release(
+    session: &mut ObservationSession,
+    validated: &ValidatedReleaseIntent<'_>,
+    repository: &GitHubRepository,
+    tag: &TagName,
+) -> CachedObservation<GitHubRelease> {
+    let key = (repository.as_slug(), tag.as_str().to_string());
+    session
+        .github_releases
+        .entry(key)
+        .or_insert_with(|| fetch_github_release(validated, repository, tag))
+        .clone()
+}
+
+fn fetch_github_release(
+    validated: &ValidatedReleaseIntent<'_>,
+    repository: &GitHubRepository,
+    tag: &TagName,
+) -> CachedObservation<GitHubRelease> {
+    let endpoint = format!("repos/{}/releases/tags/{}", repository.as_slug(), tag.as_str());
+    let args = ["api", "--include", "--method", "GET", endpoint.as_str()];
+    let output = validated
+        .runner()
+        .run_quiet("gh", &args, validated.root(), OBSERVATION_TIMEOUT)
+        .map_err(|_| ObservationFailure::Command {
+            provider: ObservationProvider::GitHub,
+        })?;
+    let (status, body) = parse_http_response(&output).ok_or(ObservationFailure::MalformedResponse {
+        provider: ObservationProvider::GitHub,
+    })?;
+    if status == 404 {
+        return Ok(None);
+    }
+    if status != 200 || !output.success() {
+        return Err(ObservationFailure::HttpStatus {
+            provider: ObservationProvider::GitHub,
+            status,
+        });
+    }
+    let value: serde_json::Value = serde_json::from_str(body).map_err(|_| ObservationFailure::MalformedResponse {
+        provider: ObservationProvider::GitHub,
+    })?;
+    if value.get("tag_name").and_then(serde_json::Value::as_str) != Some(tag.as_str()) {
+        return Err(ObservationFailure::Capability {
+            provider: ObservationProvider::GitHub,
+        });
+    }
+    let draft = value
+        .get("draft")
+        .and_then(serde_json::Value::as_bool)
+        .ok_or(ObservationFailure::MalformedResponse {
+            provider: ObservationProvider::GitHub,
+        })?;
+    let assets = parse_github_assets(value.get("assets")).ok_or(ObservationFailure::MalformedResponse {
+        provider: ObservationProvider::GitHub,
+    })?;
+    Ok(Some(GitHubRelease { draft, assets }))
+}
+
+fn parse_github_assets(value: Option<&serde_json::Value>) -> Option<BTreeMap<String, GitHubAsset>> {
+    let mut parsed = BTreeMap::new();
+    for asset in value?.as_array()? {
+        let name = asset.get("name")?.as_str()?.to_string();
+        let byte_length = asset.get("size")?.as_u64()?;
+        let digest = match asset.get("digest") {
+            Some(serde_json::Value::String(raw)) => {
+                let raw = raw.strip_prefix("sha256:")?;
+                Some(ArtifactDigest::parse(raw).ok()?)
+            }
+            Some(serde_json::Value::Null) | None => None,
+            _ => return None,
+        };
+        if parsed.insert(name, GitHubAsset { digest, byte_length }).is_some() {
+            return None;
+        }
+    }
+    Some(parsed)
+}
+
+fn fetch_pypi_version(
+    validated: &ValidatedReleaseIntent<'_>,
+    metadata_endpoint: &str,
+    package: &str,
+    version: &Version,
+) -> CachedObservation<BTreeMap<String, PypiDistribution>> {
+    let url = append_url_segments(metadata_endpoint, &[package, &version.render(), "json"]).ok_or(
+        ObservationFailure::MalformedResponse {
+            provider: ObservationProvider::Pypi,
+        },
+    )?;
+    let Some(value) = observe_json_http(validated.runner(), validated.root(), &url, ObservationProvider::Pypi)? else {
+        return Ok(None);
+    };
+    let urls = value
+        .get("urls")
+        .and_then(serde_json::Value::as_array)
+        .ok_or(ObservationFailure::MalformedResponse {
+            provider: ObservationProvider::Pypi,
+        })?;
+    let mut distributions = BTreeMap::new();
+    for file in urls {
+        let file_name = file
+            .get("filename")
+            .and_then(serde_json::Value::as_str)
+            .ok_or(ObservationFailure::MalformedResponse {
+                provider: ObservationProvider::Pypi,
+            })?
+            .to_string();
+        let byte_length = file
+            .get("size")
+            .and_then(serde_json::Value::as_u64)
+            .ok_or(ObservationFailure::MalformedResponse {
+                provider: ObservationProvider::Pypi,
+            })?;
+        let digest = file
+            .get("digests")
+            .and_then(|digests| digests.get("sha256"))
+            .and_then(serde_json::Value::as_str)
+            .and_then(|raw| ArtifactDigest::parse(raw).ok())
+            .ok_or_else(|| ObservationFailure::MissingDigest {
+                provider: ObservationProvider::Pypi,
+                file_name: file_name.clone(),
+            })?;
+        if distributions
+            .insert(digest_file_name(file_name), PypiDistribution { digest, byte_length })
+            .is_some()
+        {
+            return Err(ObservationFailure::MalformedResponse {
+                provider: ObservationProvider::Pypi,
+            });
+        }
+    }
+    Ok(Some(distributions))
+}
+
+fn digest_file_name(file_name: String) -> String {
+    file_name
+}
+
+fn observe_npm_bytes(
+    validated: &ValidatedReleaseIntent<'_>,
+    package: &str,
+    version: &Version,
+    registry: &str,
+) -> Result<Option<Vec<u8>>, ObservationFailure> {
+    let directory = tempfile::tempdir().map_err(|_| ObservationFailure::Capability {
+        provider: ObservationProvider::Npm,
+    })?;
+    let spec = format!("{package}@{}", version.render());
+    let destination = directory.path().to_string_lossy();
+    let args = [
+        "pack",
+        spec.as_str(),
+        "--json",
+        "--ignore-scripts",
+        "--pack-destination",
+        destination.as_ref(),
+        "--registry",
+        registry,
+    ];
+    let output = validated
+        .runner()
+        .run_quiet("npm", &args, validated.root(), OBSERVATION_TIMEOUT)
+        .map_err(|_| ObservationFailure::Command {
+            provider: ObservationProvider::Npm,
+        })?;
+    if !output.success() {
+        let lower = format!("{}\n{}", output.stdout, output.stderr).to_ascii_lowercase();
+        if lower.contains("e404") || lower.contains("etarget") || lower.contains("no matching version") {
+            return Ok(None);
+        }
+        return Err(ObservationFailure::Command {
+            provider: ObservationProvider::Npm,
+        });
+    }
+    let value: serde_json::Value = serde_json::from_str(&output.stdout).map_err(|_| {
+        ObservationFailure::MalformedResponse {
+            provider: ObservationProvider::Npm,
+        }
+    })?;
+    let entries = value.as_array().ok_or(ObservationFailure::MalformedResponse {
+        provider: ObservationProvider::Npm,
+    })?;
+    if entries.len() != 1 {
+        return Err(ObservationFailure::MalformedResponse {
+            provider: ObservationProvider::Npm,
+        });
+    }
+    let file_name = entries[0]
+        .get("filename")
+        .and_then(serde_json::Value::as_str)
+        .ok_or(ObservationFailure::MalformedResponse {
+            provider: ObservationProvider::Npm,
+        })?;
+    if Path::new(file_name).components().count() != 1 {
+        return Err(ObservationFailure::MalformedResponse {
+            provider: ObservationProvider::Npm,
+        });
+    }
+    std::fs::read(directory.path().join(file_name))
+        .map(Some)
+        .map_err(|_| ObservationFailure::MalformedResponse {
+            provider: ObservationProvider::Npm,
+        })
+}
+
+fn observe_json_http(
+    runner: &dyn callisto_model::CommandRunner,
+    root: &Path,
+    url: &str,
+    provider: ObservationProvider,
+) -> Result<Option<serde_json::Value>, ObservationFailure> {
+    let args = [
+        "--silent",
+        "--show-error",
+        "--location",
+        "--include",
+        "--request",
+        "GET",
+        url,
+    ];
+    let output = runner
+        .run_quiet("curl", &args, root, OBSERVATION_TIMEOUT)
+        .map_err(|_| ObservationFailure::Command { provider })?;
+    if !output.success() {
+        return Err(ObservationFailure::Command { provider });
+    }
+    let (status, body) = parse_http_response(&output).ok_or(ObservationFailure::MalformedResponse { provider })?;
+    if status == 404 {
+        return Ok(None);
+    }
+    if status != 200 {
+        return Err(ObservationFailure::HttpStatus { provider, status });
+    }
+    serde_json::from_str(body)
+        .map(Some)
+        .map_err(|_| ObservationFailure::MalformedResponse { provider })
+}
+
+fn parse_http_response(output: &CommandOutput) -> Option<(u16, &str)> {
+    parse_http_stream(&output.stdout).or_else(|| parse_http_stream(&output.stderr))
+}
+
+fn parse_http_stream(stream: &str) -> Option<(u16, &str)> {
+    let (headers, body) = stream.rsplit_once("\r\n\r\n").or_else(|| stream.rsplit_once("\n\n"))?;
+    let status = headers
+        .lines()
+        .rev()
+        .find(|line| line.trim_end_matches('\r').starts_with("HTTP/"))?
+        .split_whitespace()
+        .nth(1)?
+        .parse()
+        .ok()?;
+    Some((status, body))
+}
+
+fn cargo_metadata_url(endpoint: &str, package: &str, version: &Version) -> Option<String> {
+    let mut url = url::Url::parse(endpoint).ok()?;
+    {
+        let mut segments = url.path_segments_mut().ok()?;
+        segments.pop_if_empty();
+        if segments.pop() != Some("new") {
+            return None;
+        }
+        segments.extend([package, version.render().as_str()]);
+    }
+    Some(url.into())
+}
+
+fn append_url_segments(base: &str, segments: &[&str]) -> Option<String> {
+    let mut url = url::Url::parse(base).ok()?;
+    {
+        let mut path = url.path_segments_mut().ok()?;
+        path.pop_if_empty();
+        path.extend(segments.iter().copied());
+    }
+    Some(url.into())
+}
+
+fn malformed(provider: ObservationProvider) -> OperationObservation {
+    OperationObservation::Unverifiable(ObservationFailure::MalformedResponse { provider })
+}
