+/// Converges one validated release from external truth and writes its strict
+/// final observation receipt atomically.
+///
+/// No local journal or prior receipt is read as proof. A missing, stale,
+/// corrupt, or lost journal therefore cannot authorize an effect or block
+/// recovery. The canonical intent DAG is observed in order on every call.
+pub fn converge_release<W: ReleaseReceiptWriter>(
+    capability: &ValidatedReleaseIntent<'_>,
+    artifacts: &ValidatedArtifactManifest<'_, '_>,
+    receipt_store: &ReleaseReceiptStore<W>,
+    permit: &ApplyPermit,
+) -> Result<CompleteObservationReceipt, GraphError> {
+    let intent = capability.intent();
+    let mut observations = ObservationSession::default();
+    let mut provenance = BTreeMap::new();
+
+    for operation in intent.operations() {
+        let id = operation.id();
+        let observed = observe_prepared(&mut observations, artifacts, id);
+        if observation_satisfies_operation(id, &observed) {
+            provenance.insert(id.clone(), ObservationProvenance::AlreadyPresent);
+            continue;
+        }
+        require_dispatchable_missing_work(id, &observed)?;
+        let outcome = capability.dispatch_prepared(artifacts, &mut observations, permit, id)?;
+        provenance.insert(
+            id.clone(),
+            match outcome {
+                OperationOutcome::Published => ObservationProvenance::NewlyProduced,
+                OperationOutcome::AlreadySatisfied => ObservationProvenance::AlreadyPresent,
+                OperationOutcome::Failed | OperationOutcome::Blocked { .. } => {
+                    return Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() })
+                }
+            },
+        );
+    }
+
+    // A receipt is stronger than per-effect readback. Discard every cached
+    // provider snapshot and prove the entire roster again after all effects.
+    observations.invalidate_after_effect();
+    let mut exact = Vec::with_capacity(intent.operations().len());
+    for operation in intent.operations() {
+        let id = operation.id();
+        let evidence = match observe_prepared(&mut observations, artifacts, id) {
+            OperationObservation::Exact(evidence) => evidence,
+            OperationObservation::Conflict(_) => {
+                return Err(GraphError::ReleaseObservationConflict { operation: id.clone() })
+            }
+            OperationObservation::Unverifiable(_) => {
+                return Err(GraphError::ReleaseObservationUnverifiable { operation: id.clone() })
+            }
+            OperationObservation::Absent | OperationObservation::Incomplete(_) => {
+                return Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() })
+            }
+        };
+        exact.push(ObservedOperation::new(
+            id.clone(),
+            evidence,
+            provenance
+                .get(id)
+                .copied()
+                .unwrap_or(ObservationProvenance::AlreadyPresent),
+        ));
+    }
