+fn observation_satisfies_operation(id: &ReleaseOperationId, observed: &OperationObservation) -> bool {
+    match observed {
+        OperationObservation::Exact(_) => true,
+        OperationObservation::Incomplete(partial) => match id {
+            ReleaseOperationId::RegistryArtifactPublish { slot, .. } => {
+                !partial.missing().contains(&MissingWork::RegistryArtifact(slot.clone()))
+            }
+            _ => false,
+        },
+        OperationObservation::Absent
+        | OperationObservation::Conflict(_)
+        | OperationObservation::Unverifiable(_) => false,
+    }
