+            ) =>
+        {
+            Ok(())
+        }
+        OperationObservation::Incomplete(partial) if incomplete_authorizes_operation(id, partial) => Ok(()),
+        OperationObservation::Conflict(_) => Err(GraphError::ReleaseObservationConflict { operation: id.clone() }),
+        OperationObservation::Unverifiable(_) => {
+            Err(GraphError::ReleaseObservationUnverifiable { operation: id.clone() })
+        }
+        OperationObservation::Absent | OperationObservation::Incomplete(_) | OperationObservation::Exact(_) => {
+            Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() })
+        }
+    }
+}
+
+fn incomplete_authorizes_operation(id: &ReleaseOperationId, partial: &VerifiedPartialEvidence) -> bool {
