+//! Atomic explicit-path persistence for final observation receipts.
+//!
+//! Receipts are output evidence, never an input authority. This store exposes
+//! no load-as-proof path and accepts only a receipt that revalidates against
+//! the exact intent and artifact expectations being converged.
+
+use std::path::{Path, PathBuf};
+
+use callisto_model::{
+    atomic::atomic_write, ApplyPermit, CompleteObservationReceipt, ObservationExpectations, ReleaseIntent,
+};
+
+use crate::GraphError;
+
+pub trait ReleaseReceiptWriter {
+    fn write(&self, path: &Path, content: &str, permit: &ApplyPermit) -> std::io::Result<()>;
+}
+
+#[derive(Clone, Copy, Debug, Default)]
+pub struct AtomicReleaseReceiptWriter;
+
+impl ReleaseReceiptWriter for AtomicReleaseReceiptWriter {
+    fn write(&self, path: &Path, content: &str, permit: &ApplyPermit) -> std::io::Result<()> {
+        atomic_write(path, content, permit)
+    }
+}
+
+#[derive(Debug)]
+pub struct ReleaseReceiptStore<W = AtomicReleaseReceiptWriter> {
+    path: PathBuf,
+    writer: W,
+}
+
+impl ReleaseReceiptStore {
+    pub fn new(path: impl Into<PathBuf>) -> Self {
+        Self::with_writer(path, AtomicReleaseReceiptWriter)
+    }
+}
+
+impl<W: ReleaseReceiptWriter> ReleaseReceiptStore<W> {
+    pub fn with_writer(path: impl Into<PathBuf>, writer: W) -> Self {
+        Self {
+            path: path.into(),
+            writer,
+        }
+    }
+
+    pub fn path(&self) -> &Path {
+        &self.path
+    }
+
+    pub fn save(
+        &self,
+        intent: &ReleaseIntent,
+        expectations: &ObservationExpectations,
+        receipt: &CompleteObservationReceipt,
+        permit: &ApplyPermit,
+    ) -> Result<(), GraphError> {
+        receipt
+            .validate_for_intent(intent, expectations)
+            .map_err(|source| GraphError::ReleaseInvariant {
+                detail: format!("refused to persist a non-exact observation receipt: {source}"),
+            })?;
+        let content = serde_json::to_string_pretty(receipt)
+            .expect("closed observation receipt serialization is infallible")
+            + "\n";
+        self.writer
+            .write(&self.path, &content, permit)
+            .map_err(|error| GraphError::ReleaseStateWrite {
+                path: self.path.clone(),
+                message: error.to_string(),
+            })
+    }
+}
+
+#[cfg(test)]
+mod tests {
+    use std::io;
+
+    use super::*;
+
+    #[derive(Clone, Copy, Debug)]
+    struct FailBeforeRename;
+
+    impl ReleaseReceiptWriter for FailBeforeRename {
+        fn write(&self, _path: &Path, _content: &str, _permit: &ApplyPermit) -> io::Result<()> {
+            Err(io::Error::other("injected pre-rename failure"))
+        }
+    }
+
+    #[test]
+    fn store_has_only_an_explicit_path_and_atomic_writer_seam() {
+        let directory = tempfile::tempdir().unwrap();
+        let path = directory.path().join("receipt.json");
+        let store = ReleaseReceiptStore::with_writer(&path, FailBeforeRename);
+        assert_eq!(store.path(), path);
+        assert_eq!(std::fs::read_to_string(path).unwrap_err().kind(), io::ErrorKind::NotFound);
+    }
+}
