+fn release_with_artifacts(
+    root: &Path,
+    command: &str,
+    intent: &Path,
+    fixture: &ArtifactFixture,
+    bin: &Path,
+    mutations: &Path,
+    receipt: Option<&Path>,
+) -> Output {
+    let path = format!("{}:{}", bin.display(), std::env::var("PATH").unwrap());
+    let mut process = Command::new(env!("CARGO_BIN_EXE_callisto"));
+    process
+        .args(["--format", "json", "--cwd", root.to_str().unwrap()])
+        .args([
+            "release",
+            command,
+            "--intent",
+            intent.to_str().unwrap(),
+            "--artifact-manifest",
+            fixture.manifest.to_str().unwrap(),
+            "--artifact-dir",
+            fixture.directory.to_str().unwrap(),
+        ])
+        .env("PATH", path)
+        .env("CALLISTO_TEST_REAL_GIT", system_git())
+        .env("CALLISTO_TEST_MUTATIONS", mutations)
+        .env("CALLISTO_TEST_CARGO_RESPONSE", &fixture.cargo_response)
+        .env("CALLISTO_TEST_GITHUB_RESPONSE", &fixture.github_response);
+    if let Some(receipt) = receipt {
+        process.args(["--receipt", receipt.to_str().unwrap()]);
+    }
+    process.output().expect("release command should run")
+}
