+#[test]
+fn exact_external_release_reconciles_and_writes_an_observation_receipt_without_effects() {
+    let (dir, release_commit) = release_commit_fixture();
+    let external = tempfile::tempdir().unwrap();
+    let root = dir.path();
+    let intent_path = plan_intent(root, external.path(), &release_commit);
+    let fixture = artifact_fixture(&intent_path, external.path());
+    let tag = fixture.intent.product_release().tag();
+    git(root, &["tag", "-a", &tag, &release_commit, "-m", &format!("Release {tag}")]);
+    let (bin, mutations) = fake_observation_programs(external.path());
+
+    let reconcile = release_with_artifacts(
+        root,
+        "reconcile",
+        &intent_path,
+        &fixture,
+        &bin,
+        &mutations,
+        None,
+    );
+    assert!(
+        reconcile.status.success(),
+        "exact release must be ready: {}",
+        String::from_utf8_lossy(&reconcile.stderr)
+    );
+    let readiness: serde_json::Value = serde_json::from_slice(&reconcile.stdout).unwrap();
+    assert_eq!(readiness["operations"].as_array().unwrap().len(), fixture.intent.operations().len());
+    assert!(readiness["operations"].as_array().unwrap().iter().all(|operation| {
+        operation["observation"]["state"] == "exact" && operation["recoveryAction"] == "none"
+    }));
+
+    let receipt = external.path().join("release-receipt.json");
+    let execute = release_with_artifacts(
+        root,
+        "execute",
+        &intent_path,
+        &fixture,
+        &bin,
+        &mutations,
+        Some(&receipt),
+    );
+    assert!(
+        execute.status.success(),
+        "exact release execution failed: {}",
+        String::from_utf8_lossy(&execute.stderr)
+    );
+    let stdout_receipt: serde_json::Value = serde_json::from_slice(&execute.stdout).unwrap();
+    let disk_receipt: serde_json::Value = serde_json::from_slice(&fs::read(&receipt).unwrap()).unwrap();
+    assert_eq!(stdout_receipt, disk_receipt);
+    assert!(!mutations.exists(), "already exact convergence must perform no effect");
+}
