+    let (bin, mutations) = fake_observation_programs(external.path());
+    let output = release_with_artifacts(
+        root,
+        "reconcile",
+        &intent_path,
+        &fixture,
+        &bin,
+        &mutations,
+        None,
+    );
+    assert!(!output.status.success(), "an absent release must not report ready");
+    let readiness: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
+    assert!(readiness["operations"].as_array().unwrap().iter().any(|operation| {
+        operation["observation"]["state"] == "absent"
+            && operation["recoveryAction"] == "execute-operation"
+    }));
+    assert!(!mutations.exists(), "reconcile must never perform an external effect");
